// Copyright (c) 2026 Roshan. All rights reserved.// Proprietary license — see LICENSE file for details.package com.roshan.persona.voice.ttsimport com.roshan.persona.brain.context.AmbientSnapshotimport com.roshan.persona.brain.context.UserActivity/** * NOUS — Prosody Profile (computed by [ProsodyComputer]). * * Combines the active [VoicePersona]'s base pitch/rate with the selected * [Emotion]'s multipliers, then optionally applies an [ActivityAwareProsody] * override. The [EmotionalTtsEngine] consumes this profile to configure the * Android [android.speech.tts.TextToSpeech] engine. * * ## Composition order (§7 Emotional Prosody Engine) * * ``` * 1. Start with persona base:      VoicePersona.basePitch / baseRate * 2. Apply emotion multiplier:     × Emotion.pitchMultiplier / rateMultiplier * 3. Apply activity override:      × ProsodyOverride.rateMultiplier (optional) * 4. Clamp to TTS-safe range:      [0.5, 2.0] * 5. Apply whisper flag:           if ProsodyOverride.whisper, force pitch low * ``` * * @see <a href="docs/strategy/module-5-strategy-v2.md">§7 Emotional Prosody Engine, §21 Activity-Aware Prosody</a> */data class ProsodyProfile(    /** Final pitch multiplier (persona × emotion × activity, clamped). */    val pitch: Float,    /** Final speech rate multiplier (persona × emotion × activity, clamped). */    val rate: Float,    /** Pause pattern from the selected emotion (activity can downgrade). */    val pausePattern: PausePattern,    /** Emphasis from the selected emotion. */    val emphasis: Emphasis,    /** Volume multiplier 0.0–1.0 (1.0 = max). Defaults to 1.0 unless activity override. */    val volume: Float = 1.0f,    /** Whisper mode — drops pitch and volume dramatically (e.g. SLEEPING user). */    val whisper: Boolean = false,    /** Max response tokens the Brain should produce (activity-driven). */    val maxTokens: Int = 200,) {    init {        require(pitch in 0.5f..2.0f) { "pitch $pitch out of [0.5, 2.0]" }        require(rate in 0.5f..2.0f) { "rate $rate out of [0.5, 2.0]" }        require(volume in 0.0f..1.0f) { "volume $volume out of [0.0, 1.0]" }        require(maxTokens in 1..1000) { "maxTokens $maxTokens out of [1, 1000]" }    }    companion object {        /** TTS engine clamp bounds (Android TextToSpeech accepts 0.5–2.0). */        const val MIN_PITCH = 0.5f        const val MAX_PITCH = 2.0f        const val MIN_RATE = 0.5f        const val MAX_RATE = 2.0f        /** Clamp a float to the [min, max] range. */        internal fun clamp(value: Float, min: Float, max: Float): Float =            value.coerceIn(min, max)    }}// ──────────────────────────────────────────────────────────────────────────/** * Computes a [ProsodyProfile] from persona + emotion + optional activity override. * * Pure function — no Android dependencies — so it's trivially testable. * * ## Persona-emotion compatibility * * If the persona cannot express the requested emotion (e.g. ULTRON + HAPPY), * the emotion is downgraded to NEUTRAL before prosody is computed. This * prevents jarring mismatches like ULTRON squeaking cheerfully. * * ## Whisper mode * * If the [ProsodyOverride.whisper] flag is set (SLEEPING user), the pitch * is forced below 0.7 and the volume below 0.4 — regardless of emotion. * The Brain should also reduce maxTokens, but the prosody computer enforces * it as a safety net. */object ProsodyComputer {    /**     * Compute the final prosody profile.     *     * @param persona  active voice persona     * @param emotion  desired emotion (Brain-selected)     * @param override activity-aware override, or null if no activity context     */    fun compute(        persona: VoicePersona,        emotion: Emotion,        override: ProsodyOverride? = null,    ): ProsodyProfile {        // 1. Persona-emotion compatibility — downgrade if needed.        val effectiveEmotion = if (persona.canExpress(emotion)) emotion else Emotion.NEUTRAL        // 2. Persona base × emotion multiplier.        var pitch = persona.basePitch * effectiveEmotion.pitchMultiplier        var rate = persona.baseRate * effectiveEmotion.rateMultiplier        var volume = 1.0f        var whisper = false        var maxTokens = 200        var pausePattern = effectiveEmotion.pausePattern        // 3. Activity override (optional).        if (override != null) {            rate *= override.rateMultiplier            volume *= override.volumeMultiplier            whisper = override.whisper            maxTokens = override.maxTokens            // If the activity says "concise" (small maxTokens), reduce pauses too.            if (override.maxTokens <= 30) {                pausePattern = PausePattern.SHORT            }        }        // 4. Whisper mode forces low pitch + low volume.        if (whisper) {            pitch = minOf(pitch, 0.7f)            volume = minOf(volume, 0.4f)        }        // 5. Clamp to TTS-safe range.        pitch = ProsodyProfile.clamp(pitch, ProsodyProfile.MIN_PITCH, ProsodyProfile.MAX_PITCH)        rate = ProsodyProfile.clamp(rate, ProsodyProfile.MIN_RATE, ProsodyProfile.MAX_RATE)        volume = ProsodyProfile.clamp(volume, 0.0f, 1.0f)        return ProsodyProfile(            pitch = pitch,            rate = rate,            pausePattern = pausePattern,            emphasis = effectiveEmotion.emphasis,            volume = volume,            whisper = whisper,            maxTokens = maxTokens,        )    }}